namespace ghidra.app.plugin.core.overview;










using docking.action;
using generic.theme;
using ghidra.app.nav;
using ghidra.app.services;
using ghidra.app.util.viewer.listingpanel;
using ghidra.app.util.viewer.util;
using ghidra.framework.plugintool;
